import torch
import triton
import triton.language as tl

@triton.jit
def reduce_mean_kernel(input_ptr, output_ptr, dim, keepdim, dtype=None, out=None, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(axis=0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < input_ptr.size(0) // input_ptr.stride(0)
    if dtype is not None:
        input_ptr = input_ptr.to(dtype)
    if out is not None:
        out_ptr = out.data_ptr()
    else:
        out_ptr = output_ptr
    input = tl.load(input_ptr + offsets, mask=mask)
    if keepdim:
        output = tl.mean(input, axis=dim, keepdim=True)
    else:
        output = tl.mean(input, axis=dim, keepdim=False)
    tl.store(out_ptr + offsets, output, mask=mask)

def reduce_mean(input: torch.Tensor, dim: int | tuple[int], keepdim: bool = False, dtype: torch.dtype | None = None) -> torch.Tensor:
    n_elements = input.numel()
    grid = lambda meta: (triton.cdiv(n_elements, meta['BLOCK_SIZE']),)
    if isinstance(dim, int):
        dim = (dim,)
    reduce_mean_kernel[grid](input, input.new_empty_like(input), dim, keepdim, dtype, None, BLOCK_SIZE=1024)
    return input
