import torch
import triton
import triton.language as tl

@triton.jit
def convert_module(module, qconfig, mapping, inplace):
    if inplace:
        module._modules = {name: convert_module(submodule, qconfig, mapping, True) for name, submodule in module._modules.items()}
    else:
        new_module = type(module)(**{name: convert_module(submodule, qconfig, mapping, False) for name, submodule in module._modules.items()})
        module._modules = new_module._modules

    if isinstance(module, torch.nn.Linear):
        if 'weight' in mapping:
            new_weight = mapping['weight'](module.weight.data, qconfig)
            new_bias = mapping.get('bias', None)
            if new_bias is not None:
                new_bias = mapping['bias'](new_bias.data, qconfig)
            new_module.weight.data = new_weight
            new_module.bias.data = new_bias
        else:
            raise ValueError("Mapping does not specify weight for linear layer")

    if isinstance(module, torch.nn.Conv2d):
        if 'weight' in mapping:
            new_weight = mapping['weight'](module.weight.data, qconfig)
            new_bias = mapping.get('bias', None)
            if new_bias is not None:
                new_bias = mapping['bias'](new_bias.data, qconfig)
            new_module.weight.data = new_weight
            new_module.bias.data = new_bias
        else:
            raise ValueError("Mapping does not specify weight for convolutional layer")

    return module

def quantize_dynamic(model, qconfig_spec=None, inplace=False, mapping=None) -> Model:
    qconfig = qconfig_spec if qconfig_spec is not None else {}
    if mapping is None:
        mapping = {}

    convert_module(model, qconfig, mapping, inplace)
    return model
